// LED on D13 is on while the button on D2 is held down.
const int BUTTON = 2;
const int LED = 13;
int last = HIGH;

void setup() {
  Serial.begin(9600);
  pinMode(BUTTON, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  Serial.println("READY");
}

void loop() {
  int now = digitalRead(BUTTON);
  digitalWrite(LED, now == LOW ? HIGH : LOW);
  if (now != last) {
    Serial.println(now == LOW ? "pressed" : "released");
    last = now;
  }
}
